// ───── test harness (do not edit) ─────
function build(a) { return Queue(...a); }
const CASES = [
  { ops: ["Queue","push","push","peek","pop","count","pop"],
    args: [[],[1],[2],[],[],[],[]],
    expected: [null,null,null,1,1,1,2] },
  { ops: ["Queue","pop"], args: [[],[]], expected: [null,"THROW"] }
];
function runTests() {
  let pass=0, fail=0, firstFail=null;
  for (let c=0;c<CASES.length;c++){
    const {ops,args,expected}=CASES[c];
    let obj;
    for (let i=0;i<ops.length;i++){
      let got;
      try { if(i===0){obj=build(args[i]);got=null;} else {const r=obj[ops[i]](...args[i]);got=(r===undefined?null:r);} }
      catch(e){ got="THROW"; }
      if (JSON.stringify(got)===JSON.stringify(expected[i])) pass++;
      else { fail++; if(!firstFail) firstFail=`case ${c} op#${i} ${ops[i]}(${JSON.stringify(args[i])}) -> got ${JSON.stringify(got)}, want ${JSON.stringify(expected[i])}`; }
    }
  }
  console.log(fail===0 ? `ALL PASS (${pass} assertions)` : `${fail} failed / ${pass+fail}\n   First: ${firstFail}`);
}
runTests();
